:root{
/* ── Tipografía ── */
--font:"PdInter",Inter,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
--fs-xs:11px;--fs-sm:12px;--fs-base:13px;--fs-md:14px;--fs-card:15px;--fs-lg:16px;--fs-xl:18px;--fs-2xl:20px;--fs-3xl:24px;--fs-4xl:28px;
--fw-regular:400;--fw-medium:500;--fw-semibold:600;--fw-bold:700;--fw-black:800;
--lh-none:1;--lh-tight:1.2;--lh-snug:1.3;--lh-normal:1.45;
--ls-title:-0.3px;--ls-tight:-0.5px;--ls-caps:0.06em;
/* ── Color ── */
--fr-ink:#1F1A17;--fr-muted:#6F625A;--fr-surface:#FFF9F5;--fr-card:#FFFFFF;--fr-line:#EFE3DA;--fr-beige:#EDE4DC;
--fr-orange:#C4410C;--fr-orange-dark:#A63508;--fr-peach:#FBE6DD;--fr-peach-soft:#FDF0EA;--fr-peach-border:#E7B9A2;
--fr-green:#1F6B45;--fr-red:#B42318;
/* ── Radios ── */
--r-xs:8px;--r-sm:12px;--r-md:14px;--r-lg:18px;--r-xl:24px;--r-pill:999px;
/* ── Alturas de controles ── */
--h-sm:36px;--h-md:44px;--h-lg:48px;--h-pill:32px;--h-badge:22px;
/* ── Sombras ── */
--sh-sm:0 1px 3px rgba(31,26,23,.06);
--sh-md:0 4px 14px rgba(31,26,23,.10);
--sh-lg:0 12px 32px rgba(31,26,23,.16);
--sh-up:0 -12px 36px rgba(31,26,23,.18);
--sh-brand:0 6px 16px rgba(196,65,12,.25);
--ring:0 0 0 3px rgba(196,65,12,.12);
}

